// Domain types. Table and RPC shapes come from database.types.ts (generated by `npm run db:types`);
// this file adds the shapes of JSON columns, which the generator types as `Json`.
import type { Database } from "./database.types";

type Row<T extends keyof Database["public"]["Tables"]> = Database["public"]["Tables"][T]["Row"];

type SchoolRole = Database["public"]["Enums"]["school_role"];
type SubmissionStatus = Database["public"]["Enums"]["submission_status"];
export type Mark = "correct" | "incorrect" | "review";

/** Returned by my_context(). */
export interface Profile {
  id: string;
  email: string;
  first_name: string;
  last_name: string;
  honorific: string | null;
  must_change_password: boolean;
}

export interface Membership {
  school_id: string;
  school_name: string;
  role: SchoolRole;
}

export interface Me {
  profile: Profile;
  memberships: Membership[];
}

/** Returned by my_classes(): the classes the caller teaches. */
export type TaughtClass = Database["public"]["Functions"]["my_classes"]["Returns"][number];

export interface Question {
  id: string;
  type: "choice" | "text";
  prompt: string;
  context?: string;
  options?: string[];
  points?: number;
}

export interface Section {
  id: string;
  title: string;
  instructions?: string;
  questions: Question[];
}

interface AssignmentContent {
  sections: Section[];
}

export type Assignment = Omit<Row<"assignments">, "content"> & { content: AssignmentContent };

export interface KeyEntry {
  correct?: number;
  accept?: string[];
  explanation?: string;
}
export type AnswerKey = Record<string, KeyEntry>;

/** Choice questions store the original option index; text questions store the text. */
export type Answers = Record<string, number | string>;

/** Returned by the my_submission_detail() RPC. Feedback fields are null until the work is returned. */
export interface MySubmissionDetail {
  status: SubmissionStatus;
  submitted_at: string;
  returned_at: string | null;
  answers: Answers;
  score: number | null;
  max_score: number | null;
  marks: Record<string, Mark> | null;
  question_comments: Record<string, string> | null;
  teacher_comment: string | null;
  key: AnswerKey | null;
}

export type Submission = Omit<Row<"submissions">, "answers" | "auto_results" | "teacher_marks" | "question_comments"> & {
  answers: Answers;
  auto_results: Record<string, Mark>;
  teacher_marks: Record<string, Mark>;
  question_comments: Record<string, string>;
};
